// Optional account dialog. Firebase is loaded only when a configured user opens it.
export function installAccountUI({button,loadAdapter,onUser,importGuest,exportLocal,clearAccount,onError=()=>{}}){
 let adapter=null,loading=null,unsubscribe=null,user=null,revision=0,busy=false;
 const dialog=document.createElement('dialog');dialog.className='account-dialog';document.body.append(dialog);
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const q=s=>dialog.querySelector(s);
 async function ready(){if(adapter)return adapter;if(!loading)loading=loadAdapter().then(a=>{adapter=a;unsubscribe=a.onAuth(u=>{user=u;onUser(u,a);button.textContent=u?'Account ✓':'Account';if(dialog.open&&!busy)show()});return a}).finally(()=>{loading=null});return loading}
 function close(){revision++;dialog.querySelectorAll('input[type="password"]').forEach(e=>e.value='');dialog.close()}
 function status(s){const el=q('[role="status"]');if(el)el.textContent=s}
 function show(){revision++;busy=false;dialog.innerHTML=`<div class="dialoghead"><h2>Your workshop account</h2><button data-close aria-label="Close account">×</button></div>${user?`<p>Signed in as ${escape(user.email)}. Guest progress remains separate.</p><p>Only completed puzzle scores sync. No leaderboards or tracking.</p><button data-import>Import this browser’s guest scores…</button><button data-export>Export my progress</button><button data-out>Sign out</button><details><summary>Delete account and cloud progress</summary><p>This permanently deletes your account and its cloud scores. Guest progress is not deleted. Enter your password to confirm.</p><label>Password<input data-delete-password type="password" autocomplete="current-password"></label><button data-delete>Delete account and cloud progress</button></details>`:`<p>Optional: save completed scores across devices. Keep playing as a guest if you prefer. No automatic import of this browser’s guest progress.</p><form><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required minlength="6"></label><button type="submit">Sign in</button><button type="button" data-signup>Create account</button><button type="button" data-reset>Send password reset email</button></form>`}<p role="status" aria-live="polite"></p>`;
 q('[data-close]').onclick=close;
 const run=async fn=>{if(busy)return;busy=true;const ticket=revision;dialog.querySelectorAll('button').forEach(b=>{if(b!==q('[data-close]'))b.disabled=true});try{await fn();if(ticket===revision&&dialog.open)status('Done.')}catch(e){if(ticket===revision&&dialog.open)status(e?.code==='auth/invalid-credential'?'Sign-in failed. Check your email and password.':'That action could not finish. Your saved progress has not been replaced. Please try again.');onError(e)}finally{dialog.querySelectorAll('input[type="password"]').forEach(e=>e.value='');if(ticket===revision){busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false)}}};
 if(user){q('[data-out]').onclick=()=>run(async()=>{await adapter.signOut();show()});q('[data-import]').onclick=()=>{q('[data-import]').textContent='Confirm import: keep the better score for each matching puzzle';q('[data-import]').onclick=()=>run(async()=>{await importGuest();status('Guest scores imported. Original guest progress is unchanged.')})};q('[data-export]').onclick=()=>run(async()=>{const value=await exportLocal();const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='screw-workshop-progress.json';a.click();URL.revokeObjectURL(url)});q('[data-delete]').onclick=()=>run(async()=>{const uid=user.uid,p=q('[data-delete-password]').value;if(!p)throw Error('Password required');await adapter.deleteAccount(p);clearAccount(uid);show()})}
 else{const creds=()=>({email:q('[name="email"]').value.trim(),password:q('[name="password"]').value});const auth=method=>run(async()=>{const c=creds();await adapter[method](c.email,c.password);show()});q('form').onsubmit=e=>{e.preventDefault();auth('signIn')};q('[data-signup]').onclick=()=>auth('signUp');q('[data-reset]').onclick=()=>run(async()=>{await adapter.resetPassword(creds().email)})}
 }
 button.hidden=false;button.onclick=async()=>{const ticket=++revision;button.disabled=true;try{await ready();if(ticket!==revision)return;show();dialog.showModal()}catch(e){onError(e);button.textContent='Account unavailable — retry'}finally{button.disabled=false}};
 dialog.addEventListener('cancel',()=>{revision++});dialog.addEventListener('close',()=>{revision++;dialog.querySelectorAll('input[type="password"]').forEach(e=>e.value='')});
 return {close,getUser:()=>user,destroy(){unsubscribe?.();close();dialog.remove()}};
}
export function scoreRecord(kind,puzzleId,revision,bestMoves){return {schema:1,kind,puzzleId,revision,bestMoves,completed:true}}
export function dailyScoreRecord(identity,bestMoves){const match=/^([a-z0-9-]{1,96})@([a-f0-9]{64})$/.exec(identity||'');return match?scoreRecord('daily',match[1],match[2],bestMoves):null}
